package autonewsroller.video;

import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.TimeUnit;
public final class FfmpegRunner {public static String run(List<String>cmd,int timeout)throws Exception{ProcessBuilder b=new ProcessBuilder(cmd);b.redirectErrorStream(true);Process p=b.start();StringBuilder out=new StringBuilder();Thread t=new Thread(()->{try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream(),StandardCharsets.UTF_8))){for(String l;(l=r.readLine())!=null;)out.append(l).append('\n');}catch(IOException ignored){}});t.start();if(!p.waitFor(Math.max(1,timeout),TimeUnit.SECONDS)){p.destroyForcibly();throw new IOException("FFmpeg process timed out: "+String.join(" ",cmd));}t.join(1000);if(p.exitValue()!=0)throw new IOException("FFmpeg failed ("+p.exitValue()+"): "+tail(out.toString()));return out.toString();}private static String tail(String s){s=s.trim();return s.length()>3000?s.substring(s.length()-3000):s;}}
